// CONCRETE EXAMPLE: Longest subarray with sum <= target (positive integers)
function longestSubarraySumAtMost(nums, target) {
    let left = 0, windowSum = 0, maxLen = 0;

    for (let right = 0; right < nums.length; right++) {
        windowSum += nums[right];           // EXPAND: add right element

        while (windowSum > target) {        // SHRINK: sum exceeds target
            windowSum -= nums[left];
            left++;
        }
        maxLen = Math.max(maxLen, right - left + 1); // RECORD valid window
    }
    return maxLen;
}

// CONCRETE EXAMPLE: Shortest subarray with sum >= target (positive integers)
function shortestSubarraySumAtLeast(nums, target) {
    let left = 0, windowSum = 0, minLen = Infinity;

    for (let right = 0; right < nums.length; right++) {
        windowSum += nums[right];           // EXPAND

        while (windowSum >= target) {       // SHRINK while valid: find minimum
            minLen = Math.min(minLen, right - left + 1); // RECORD inside while
            windowSum -= nums[left];
            left++;
        }
    }
    return minLen === Infinity ? 0 : minLen;
}

