// LONGEST SUBSTRING WITHOUT REPEATING (#3)

// APPROACH 1: Set-based O(n)
function lengthOfLongestSubstring_set(s) {
    const charSet = new Set();
    let left = 0, maxLen = 0;
    for (let right = 0; right < s.length; right++) {
        while (charSet.has(s[right])) {   // shrink until no duplicate
            charSet.delete(s[left]);
            left++;
        }
        charSet.add(s[right]);
        maxLen = Math.max(maxLen, right - left + 1);
    }
    return maxLen;
}

// APPROACH 2: Map-based O(n) with direct jump (no inner while)
function lengthOfLongestSubstring(s) {
    const lastSeen = new Map(); // char -> last seen index
    let left = 0, maxLen = 0;
    for (let right = 0; right < s.length; right++) {
        if (lastSeen.has(s[right])) {
            // Jump left past the previous occurrence
            // BUT never move left backward (max with current left)
            left = Math.max(left, lastSeen.get(s[right]) + 1);
        }
        lastSeen.set(s[right], right); // update last seen index
        maxLen = Math.max(maxLen, right - left + 1);
    }
    return maxLen;
}

