// MINIMUM WINDOW SUBSTRING (#76)
// O(n + |t|) time, O(|t|) space
function minWindow(s, t) {
    if (!t.length || !s.length) return '';

    // BUILD NEED MAP from t
    const need = new Map();
    for (const c of t) need.set(c, (need.get(c) || 0) + 1);

    const required = need.size; // number of distinct chars needed
    const window = new Map();   // current window char frequencies
    let have = 0;               // chars in t with window_freq >= need_freq

    let left = 0;
    let minLen = Infinity, minStart = 0;

    for (let right = 0; right < s.length; right++) {
        // EXPAND: add s[right] to window
        const c = s[right];
        window.set(c, (window.get(c) || 0) + 1);

        // Check if this character's requirement is now satisfied
        if (need.has(c) && window.get(c) === need.get(c)) {
            have++; // exactly met (not exceeded): increment have
        }

        // SHRINK: while all requirements satisfied, find minimum window
        while (have === required) {
            // Update minimum if current window is smaller
            if (right - left + 1 < minLen) {
                minLen = right - left + 1;
                minStart = left;
            }

            // Remove s[left] from window
            const lc = s[left];
            window.set(lc, window.get(lc) - 1);
            if (need.has(lc) && window.get(lc) < need.get(lc)) {
                have--; // requirement no longer met: decrement have
            }
            left++;
        }
    }
    return minLen === Infinity ? '' : s.slice(minStart, minStart + minLen);
}

