function minWindowImpl(s, t) {
  if(!t.length||!s.length)return'';
  const need=new Map();
  for(const c of t)need.set(c,(need.get(c)||0)+1);
  const req=need.size,win=new Map();
  let have=0,l=0,minLen=Infinity,minStart=0;
  for(let r=0;r<s.length;r++){
    const c=s[r];
    win.set(c,(win.get(c)||0)+1);
    if(need.has(c)&&win.get(c)===need.get(c))have++;
    while(have===req){
      if(r-l+1<minLen){minLen=r-l+1;minStart=l;}
      const lc=s[l];
      win.set(lc,win.get(lc)-1);
      if(need.has(lc)&&win.get(lc)<need.get(lc))have--;
      l++;
    }
  }
  return minLen===Infinity?'':s.slice(minStart,minStart+minLen);
}

