// SLIDING WINDOW MAXIMUM (#239)
// O(n) time, O(k) space
function maxSlidingWindow(nums, k) {
    const deque = []; // stores INDICES in decreasing order of nums values
    const result = [];

    for (let i = 0; i < nums.length; i++) {
        // STEP 1: Remove expired indices from front (left the window)
        if (deque.length && deque[0] < i - k + 1) {
            deque.shift(); // front is out of window
        }

        // STEP 2: Remove from back indices whose values <= nums[i]
        // They can never be the maximum while nums[i] is in the window
        while (deque.length && nums[deque[deque.length-1]] <= nums[i]) {
            deque.pop(); // remove from back
        }

        // STEP 3: Push current index to back
        deque.push(i);

        // STEP 4: Record result when window is full
        if (i >= k - 1) {
            result.push(nums[deque[0]]); // front = index of current max
        }
    }
    return result;
}

