// TRAPPING RAIN WATER (#42)

// PRECOMPUTED APPROACH: O(n) time, O(n) space
function trap_precomputed(height) {
    const n = height.length;
    const maxLeft  = new Array(n).fill(0);
    const maxRight = new Array(n).fill(0);

    maxLeft[0] = height[0];
    for (let i = 1; i < n; i++) maxLeft[i] = Math.max(maxLeft[i-1], height[i]);

    maxRight[n-1] = height[n-1];
    for (let i = n-2; i >= 0; i--) maxRight[i] = Math.max(maxRight[i+1], height[i]);

    let water = 0;
    for (let i = 0; i < n; i++) {
        water += Math.min(maxLeft[i], maxRight[i]) - height[i];
    }
    return water;
}

// TWO-POINTER APPROACH: O(n) time, O(1) space
function trap(height) {
    let left = 0, right = height.length - 1;
    let maxLeft = 0, maxRight = 0;
    let water = 0;

    while (left < right) {
        if (height[left] < height[right]) {
            // Left side is the bottleneck: maxLeft determines water level
            if (height[left] >= maxLeft) {
                maxLeft = height[left]; // update running max
            } else {
                water += maxLeft - height[left]; // trapped water
            }
            left++;
        } else {
            // Right side is the bottleneck: maxRight determines water level
            if (height[right] >= maxRight) {
                maxRight = height[right];
            } else {
                water += maxRight - height[right];
            }
            right--;
        }
    }
    return water;
}

